import { Engine, XO_SUPPORTED_NETWORKS } from '@xo-cash/engine';
import { p2pkhTemplate } from '@xo-cash/templates';
import { mkdirSync } from 'node:fs';
import { DEFAULT_DB_PATH, loadWalletConfig } from './lib/config.js';

/**
 * Recovery helper (FINDINGS 11).
 *
 * XO derives every generated key from a per-account counter that lives in the
 * account database. Recreating the database therefore rewinds the counter, and
 * change outputs generated by the previous database become invisible to the
 * engine even though the mnemonic is unchanged: nothing on disk is lost, but
 * nothing re-subscribes to those script hashes either. This walks the counter
 * forward again (generating the same addresses) until the target script shows
 * up, which makes the engine subscribe to it and re-ingest its UTXOs.
 *
 *   TARGET_SCRIPT=<script hex> node --import tsx scripts/recover-change.ts 40
 */
const targetScript = process.env.TARGET_SCRIPT ?? '76a914bd7046df01b5a084a9a52cf6f59f82e59ad5f44c88ac';
const attempts = Number(process.argv[2] ?? '40');
const wallet = loadWalletConfig();
const databasePath = process.env.XO_DB_PATH ?? DEFAULT_DB_PATH;
mkdirSync(databasePath, { recursive: true });
const engine = await Engine.create(wallet.mnemonic, { network: XO_SUPPORTED_NETWORKS.chipnet, databasePath });
try {
    const { templateIdentifier } = await engine.importTemplate(p2pkhTemplate);
    await engine.setDefaultPolicies({
        receive: { templateIdentifier },
        change: { templateIdentifier },
        address: { templateIdentifier },
    });
    for (let attempt = 1; attempt <= attempts; attempt += 1) {
        const script = await engine.generateLockingBytecodeFromDefaultPolicy('change');
        process.stdout.write(`attempt ${attempt}: ${script}${script === targetScript ? '  <-- target' : ''}\n`);
        if (script === targetScript) break;
    }
    await new Promise((resolve) => setTimeout(resolve, 10_000));
    const utxos = await engine.listSpendableUnspentOutputs();
    let total = 0n;
    for (const utxo of utxos) total += BigInt(utxo.valueSatoshis);
    console.log('TOTAL', String(total), 'utxos', utxos.length);
    for (const utxo of utxos.filter((candidate) => BigInt(candidate.valueSatoshis) > 20_000n)) {
        console.log('LARGE', `${utxo.outpointTransactionHash}:${utxo.outpointIndex}`, String(utxo.valueSatoshis));
    }
} finally {
    await engine.stop();
}
